/**
 * @method
 * @name scwin.makeInputFromParent
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.makeInputFromParent = function () {
    /* sdd-asis-lifecycle:begin makeInputFromParent — as-is 원문 본문(전환 이관 · 포팅 적용됨) */

    const parentfm = ((((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).scwin || {}))["SendForm"] !== undefined ? (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).scwin || {}))["SendForm"] : undefined);
    const fm = (document.InputForm || { elements: [] });
    $c.util.getComponent("ipt_equivRedmptVal").setValue(parentfm.equiv_redmpt_val.value);
    $c.util.getComponent("ipt_defrMms").setValue(parentfm.defr_mms.value);
    $c.util.getComponent("slc_redmptPdIntTpCd").setValue(parentfm.redmpt_pd_int_tp_cd.value);
    $c.util.getComponent("ipt_splitRedmptCnt").setValue(parentfm.split_redmpt_cnt.value);
    $c.util.getComponent("cal_fstSplitRedmptDd").setValue(parentfm.fst_split_redmpt_dd.value);
    $c.util.getComponent("ipt_splitRedmptCycle").setValue(parentfm.split_redmpt_cycle.value);
    const v_str = parentfm.split_redmpt_mmend_tp_cd.value;
    if (v_str === '1') {
        /* 수동 전환 필요: split_redmpt_mmend_tp_cd[0] 선택 — 옵션표 미해결 */ void 0;
    } else {
        if (v_str === '2') {
            /* 수동 전환 필요: split_redmpt_mmend_tp_cd[1] 선택 — 옵션표 미해결 */ void 0;
        }
    }
    $("input[name='equiv_redmpt_val']").trigger('onkeyup');
    $("input[name='equiv_redmpt_val']").trigger('onfocus');
    if (parentfm.non_eq_count.value === '') {
        scwin.rownum = 0;
    } else {
        scwin.rownum = parseInt(parentfm.non_eq_count.value);
    }
    let temprow = 0;
    if (scwin.rownum > 0) {
        temprow = scwin.rownum;
        $("#tbl_non_eq tr").remove();
        scwin.rownum = 0;
        for (let i = 1; i < temprow + 1; i++) {
            scwin.addRow();
            if (temprow == 1) {
                $c.util.getComponent("fm.int_pay_dd_" + i).setValue(eval("parentfm.arr_int_pay_dd.value"));
                $c.util.getComponent("fm.redmpt_amt_" + i).setValue(eval("parentfm.arr_redmpt_amt.value"));
            } else {
                if (temprow > 1) {
                    $c.util.getComponent("fm.int_pay_dd_" + i).setValue(eval("parentfm.arr_int_pay_dd[" + (i - 1) + "].value"));
                    $c.util.getComponent("fm.redmpt_amt_" + i).setValue(eval("parentfm.arr_redmpt_amt[" + (i - 1) + "].value"));
                }
            }
        }
    } else {
        scwin.rownum = 1;
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.data_Chk
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.data_Chk = async function () {
    /* sdd-asis-lifecycle:begin data_Chk — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fm = (document.InputForm || { elements: [] });
    if ($c.str.getByteLength($c.util.getComponent('ipt_equivRedmptVal').getValue()) == 0) {
        await $c.win.alert("균등상환액을 입력하십시오.");
        $c.util.getComponent("ipt_equivRedmptVal").focus();
        return false;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_defrMms').getValue()) == 0) {
        await $c.win.alert("거치기간을 입력하십시오.");
        $c.util.getComponent("ipt_defrMms").focus();
        return false;
    }
    if ($c.util.getComponent('slc_redmptPdIntTpCd').getValue() === '') {
        await $c.win.alert("거치기간이자를 선택하십시오.");
        $c.util.getComponent("slc_redmptPdIntTpCd").focus();
        return false;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_splitRedmptCnt').getValue()) == 0) {
        await $c.win.alert("분할상환횟수를 입력하십시오.");
        $c.util.getComponent("ipt_splitRedmptCnt").focus();
        return false;
    }
    if ($c.str.getByteLength($c.util.getComponent('cal_fstSplitRedmptDd').getValue()) == 0) {
        await $c.win.alert("최초분할상환일을 입력하십시오.");
        $c.util.getComponent("cal_fstSplitRedmptDd").focus();
        return false;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_splitRedmptCycle').getValue()) == 0) {
        await $c.win.alert("상환주기를 입력하십시오.");
        $c.util.getComponent("ipt_splitRedmptCycle").focus();
        return false;
    }
    return true;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.div_send_form
 * @author Inswave
 * @date 2026. 09. 29
 * @param index
 * @returns
 * @hidden N
*/
