/**
 * @method
 * @name scwin.addRow
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.addRow = function () {
    /* sdd-asis-lifecycle:begin fn_addRow — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fm = (document.InputForm || { elements: [] });
    const rowPlus = $c.util.getComponent("tbl_non_eq");
    let tr;
    let th;
    let td;
    const newRowNum = scwin.rownum + 1;
    const $tblNonEq = $('#tbl_non_eq');
    const $tr = $("<tr></tr>");
    const $td1 = $("<td>" + newRowNum + "</td>").addClass('first txc');
    const $td2 = $("<td><div style=\"display:flex; align-items:center;\"><input type=\"text\" id=\"int_pay_dd_" + newRowNum + "\" name=\"int_pay_dd_" + newRowNum + "\" value=\"\" maxlength=8 class=\"txt input-calendar\" title=\"날짜입력\" onBlur=\"Chk_Date2( this,'이자지급일 " + newRowNum + "차' )\" onfocus=\"cal_offMask('document.InputForm.int_pay_dd_" + newRowNum + "')\" onkeyup=\"chkDate('document.InputForm.int_pay_dd_" + newRowNum + "')\" style=\"height: 24px;\" /></div></td>");
    const $td3 = $("<td><input type=\"text\" name=\"redmpt_amt_" + newRowNum + "\"  value=\'" + $c.util.getComponent('ipt_equivRedmptVal').getValue()+ "\' maxlength=18 class=\"txt short\" style=\"text-align: right;IME-MODE:disabled;width: 200px;border: none;\" onkeypress=\"NumberCheck(this)\" onFocus=\'Del_MoneyComma(this);\' onBlur=\'Add_MoneyComma(this);\' readonly=\'readonly\' /></td>");
    $tr.append($td1);
    $tr.append($td2);
    $tr.append($td3);
    $tblNonEq.append($tr);
    scwin.rownum++;
    $("#int_pay_dd_" + newRowNum).datepicker(myDateOpts);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.delRow
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.delRow = async function () {
    /* sdd-asis-lifecycle:begin fn_delRow — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const rowPlus = $c.util.getComponent("tbl_non_eq");
    if (scwin.rownum > 0) {
        const no = rowPlus.rows.length - 1;
        rowPlus.deleteRow(no);
        scwin.rownum--;
    } else {
        if (scwin.rownum < 1) {
            await $c.win.alert("삭제 할 행이 없습니다.");
        }
    }
    /* sdd-asis-lifecycle:end */
};


// [A] 초기 목록 미해결 — jldbnf05008: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)
/**
 * @method
 * @name scwin.autoCalcDone
 * @author Inswave
 * @date 2026. 09. 29
 * @param data
 * @returns
 * @hidden N
*/
scwin.autoCalcDone = function (data) {
    /* sdd-asis-lifecycle:begin fn_autoCalc_done — as-is 원문 본문(전환 이관 · 포팅 적용됨) */scwin.result = (typeof data === "string" ? JSON.parse(data) : data);
    $(scwin.result.arrList).each(function(i, item) {
            if (i == 0) {
                $c.util.getComponent('cal_intPayDd1').setValue(item.day);
                $c.util.getComponent('ipt_redmptAmt1').setValue(item.val);
            } else {
                scwin.addRow();
                $("input[name='int_pay_dd_" + (i + 1) + "']").val(item.day);
                $("input[name='redmpt_amt_" + (i + 1) + "']").val(item.val);
            }
    });
    /* sdd-asis-lifecycle:end */
};

/**
 * @method
 * @name scwin.autoCalc
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.autoCalc = async function () {
    const r = await scwin.tx_fn_autoCalc();
    try {
        scwin.autoCalcDone.call(window, JSON.stringify((r && r.responseJSON && (r.responseJSON.body != null ? r.responseJSON.body : r.responseJSON)) || {}));
    }
    catch (_se) {
        await $c.exception.handleError(_se, { notify: 'none', context: 'jldbnf05008.fn_autoCalc' });
    }
    return r;
};
